// Obtiene todos los items que llegan al nodo Code
const items = $input.all();

// Variable donde vamos a guardar la suma de los tres puntajes
let suma = 0;

// Recorremos todos los items recibidos
for (const item of items) {
  suma += Number(item.json.puntaje_nutriments_azucar_100g) || 0;
  suma += Number(item.json.puntaje_nutriments_sal_100g) || 0;
  suma += Number(item.json.puntaje_nutriments_grasa_100g) || 0;
}

// Determinamos la clasificación según el resultado de la suma
let resultado;

if (suma === 0) {
  resultado = "Saludable";
} else if (suma === 1) {
  resultado = "Moderado";
} else {
  resultado = "No saludable";
}

// Devolvemos un único item con los dos valores que necesitamos
return [
  {
    json: {
      suma_puntajes: suma,
      resultado: resultado
    }
  }
];

// Obtener todos los items que llegan al nodo
const items = $input.all();

// Obtener los tres resultados
const resultadoPuntajes = items[0].json.resultado;
const resultadoNutriscore = items[1].json.nutriscore_result;


// Buscar el item que tenga el campo "product"
const itemProducto = items.find(item => item.json.product !== undefined);
// Obtener product
const productoInfo = itemProducto?.json.product;


// Definir qué tan malo es cada resultado.
// Cuanto mayor sea el número, peor es el resultado.
const nivel = {
  "Saludable": 0,
  "Moderado": 1,
  "No saludable": 2
};


// Comparar ambos resultados.
// Si son iguales, devuelve ese mismo valor.
// Si son distintos, devuelve el peor.
let resultadoFinal;

if (resultadoPuntajes === resultadoNutriscore) {
  resultadoFinal = resultadoPuntajes;
} else {
  resultadoFinal =
    nivel[resultadoPuntajes] > nivel[resultadoNutriscore]
      ? resultadoPuntajes
      : resultadoNutriscore;
}


// Devolver un único JSON
return [
  {
    json: {
      resultado: resultadoFinal,
      product: productoInfo
    }
  }
];
